def should_retry(status, error):
    if status is not None:
        if status == 429:
            return True
        if 500 <= status < 600:
            return True
        return False
    else:
        if error in ("timeout", "connection"):
            return True
        return False

from retry import should_retry

def test_should_retry_429():
    assert should_retry(429, None) == True

def test_should_retry_5xx():
    assert should_retry(500, None) == True
    assert should_retry(502, None) == True
    assert should_retry(503, None) == True
    assert should_retry(599, None) == True

def test_should_retry_4xx():
    assert should_retry(400, None) == False
    assert should_retry(401, None) == False
    assert should_retry(404, None) == False

def test_should_retry_timeout_error():
    assert should_retry(None, "timeout") == True

def test_should_retry_connection_error():
    assert should_retry(None, "connection") == True

def test_should_retry_unknown_error():
    assert should_retry(None, "unknown") == False
    assert should_retry(None, "notfound") == False

def test_should_retry_none_status_none_error():
    assert should_retry(None, None) == False

def test_should_retry_429_with_error():
    assert should_retry(429, "timeout") == True

def test_should_retry_500_with_error():
    assert should_retry(500, "timeout") == True

def test_should_retry_401_with_error():
    assert should_retry(401, "timeout") == False
